import{_ as o,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Projetos e ambientes","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/projects.md","filePath":"pt-BR/guide/projects.md"}'),t={name:"pt-BR/guide/projects.md"};function r(n,e,p,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="projetos-e-ambientes" tabindex="-1">Projetos e ambientes <a class="header-anchor" href="#projetos-e-ambientes" aria-label="Permalink to &quot;Projetos e ambientes&quot;">​</a></h1><h2 id="projects" tabindex="-1">Projetos <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projetos {#projects}&quot;">​</a></h2><p>Um projeto agrupa as aplicações e os bancos de um produto. Cada projeto começa com um ambiente de <strong>produção</strong> e pode ter também <strong>staging</strong> e <strong>desenvolvimento</strong>.</p><ul><li><p>Cada ambiente é separado: seus próprios serviços, variáveis, bancos e endereços. Uma aplicação só alcança os bancos do seu próprio ambiente.</p></li><li><p>No servidor, cada ambiente é um namespace do Kubernetes chamado <code>orbit-&lt;projeto&gt;-&lt;ambiente&gt;</code>, com o nome que o projeto tinha ao ser criado:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy,pods,ingress,certificates</span></span></code></pre></div></li></ul><h2 id="changing" tabindex="-1">Mudando e apagando <a class="header-anchor" href="#changing" aria-label="Permalink to &quot;Mudando e apagando {#changing}&quot;">​</a></h2><p>Nas <strong>Configurações</strong> do projeto, ao lado dos ambientes:</p><ul><li><strong>Nome, descrição e cor.</strong> Um nome novo não pode ser um que outro projeto usa ou já usou. O que já roda mantém o namespace e os endereços; só serviços adicionados depois usam o nome novo no endereço gerado.</li><li><strong>Remover staging ou desenvolvimento.</strong> Tudo dentro dele para e é removido com seus dados, e os previews que o copiavam são desligados. A produção fica enquanto o projeto existir.</li><li><strong>Apagar o projeto.</strong> Todos os ambientes, previews, aplicações e bancos vão embora, com seus dados.</li><li><strong>Apagar uma aplicação</strong> fica no fim das suas Configurações. Um <strong>banco</strong> tem a mesma seção na sua página e é recusado enquanto alguma aplicação ainda o referencia: desconecte antes.</li></ul><p>Toda remoção pede que você digite o nome. Os arquivos de backup ficam: os locais em <code>/var/lib/orbit/backups/&lt;id do banco&gt;</code>, os externos no seu bucket.</p><h2 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces {#workspaces}&quot;">​</a></h2><ul><li><strong>O que pertence a um workspace:</strong> projetos (com ambientes, serviços, bancos e backups), as conexões com o GitHub, o GitLab e o Bitbucket, credenciais de registry, armazenamentos de backup e atividade. Os servidores são compartilhados por todos os workspaces.</li><li><strong>Trocar:</strong> pelo seletor no topo da barra lateral. Cada navegador lembra o último usado, e abrir o link de um projeto de outro workspace troca para ele.</li><li><strong>GitHub, GitLab e Bitbucket por workspace:</strong> cada workspace conecta a sua própria conta ou organização do GitHub, o seu próprio GitLab e o seu próprio workspace do Bitbucket, então um workspace &quot;Pessoal&quot; pode ler a sua conta enquanto um &quot;Cortex Labs&quot; lê a organização.</li><li><strong>Nomes:</strong> nomes de projeto são únicos em todo o Orbit, porque nomeiam o namespace do Kubernetes e o endereço gerado.</li><li><strong>Criar e renomear:</strong> em Configurações → Workspace. Só o administrador do Orbit cria workspaces.</li><li><strong>Pessoas:</strong> cada workspace tem os seus membros e papéis. Veja <a href="./members">Membros e papéis</a>.</li></ul>',10)])])}const g=o(t,[["render",r]]);export{m as __pageData,g as default};
